package com.example.audit.api;
import com.example.audit.config.AppProperties; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") public class AuthController { private final JwtEncoder encoder; private final AppProperties props; public AuthController(JwtEncoder e,AppProperties p){encoder=e;props=p;}
 public record Login(String username,String password){} public record Token(String accessToken,String tokenType,long expiresIn,String scope){}
 @PostMapping("/token") public ResponseEntity<?> token(@RequestBody Login login){ Map<String,String> users=Map.of("writer","writer123","reader","reader123","admin","admin123"); if(!Objects.equals(users.get(login.username()),login.password()))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error","invalid_credentials")); String scope=switch(login.username()){case "writer"->"AUDIT_WRITER AUDIT_READER";case "reader"->"AUDIT_READER";default->"AUDIT_WRITER AUDIT_READER AUDIT_ADMIN AUDIT_EXPORTER";}; Instant now=Instant.now(); long exp=props.jwt().expirationMinutes()*60; JwtClaimsSet claims=JwtClaimsSet.builder().issuer(props.jwt().issuer()).issuedAt(now).expiresAt(now.plusSeconds(exp)).subject(login.username()).claim("scope",scope).build(); JwsHeader header=JwsHeader.with(MacAlgorithm.HS256).build(); return ResponseEntity.ok(new Token(encoder.encode(JwtEncoderParameters.from(header,claims)).getTokenValue(),"Bearer",exp,scope)); }
}
